mapper.select:
select id, run_id, status, snapshot_json, created_at, updated_at from agent_run_context
and run_id = #{runId}
limit 1

mapper.update:
update agent_run_context
set status = #{status}

  and run_id = #{runId}

mapper.delete:
delete from agent_run_context
where run_id in (
    select run_id
    from agent_run
    where agent_id = #{agentId}
)
